import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"包管理工具","description":"","frontmatter":{},"headers":[],"relativePath":"web/front/project/pack-tools.md","filePath":"web/front/project/pack-tools.md"}`),a={name:`web/front/project/pack-tools.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="包管理工具" tabindex="-1">包管理工具 <a class="header-anchor" href="#包管理工具" aria-label="Permalink to “包管理工具”">​</a></h1><ul><li>统一包管理工具，防止不同项目使用不同的包管理工具，造成依赖冲突。</li></ul><h2 id="先上总结" tabindex="-1">先上总结 <a class="header-anchor" href="#先上总结" aria-label="Permalink to “先上总结”">​</a></h2><ul><li><strong>npm</strong>：适合绝大多数项目，默认安装，生态系统庞大。</li><li><strong>pnpm</strong>（推荐使用）：适合大型项目和需要高性能的项目，安装速度快，节省磁盘空间。</li><li><strong>bun</strong>：新一代运行时 + 包管理器，速度极快。</li></ul><h2 id="npm" tabindex="-1">npm <a class="header-anchor" href="#npm" aria-label="Permalink to “npm”">​</a></h2><ul><li>npm（Node Package Manager）是 Node.js 的默认包管理工具，用于管理项目依赖和发布 Node.js 模块。</li><li>它是最常用的包管理工具之一。</li></ul><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to “优点”">​</a></h3><ul><li>生态系统庞大，社区活跃。</li><li>简单易用，默认安装。</li></ul><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to “缺点”">​</a></h3><ul><li>安装速度较慢，依赖树结构复杂，可能导致重复安装依赖。</li></ul><h2 id="pnpm" tabindex="-1">pnpm <a class="header-anchor" href="#pnpm" aria-label="Permalink to “pnpm”">​</a></h2><ul><li>pnpm（Performant npm）是一种高性能的包管理工具，通过硬链接和符号链接的方式来共享依赖，节省磁盘空间并提升安装速度。</li></ul><h3 id="优点-1" tabindex="-1">优点 <a class="header-anchor" href="#优点-1" aria-label="Permalink to “优点”">​</a></h3><ul><li>安装速度快，性能优越。</li><li>节省磁盘空间，依赖管理严格。</li><li>与 npm 命令兼容，使用方便。</li></ul><h3 id="缺点-1" tabindex="-1">缺点 <a class="header-anchor" href="#缺点-1" aria-label="Permalink to “缺点”">​</a></h3><ul><li>生态系统和社区相对较小。</li><li>一些包不支持 pnpm。</li></ul><h2 id="bun" tabindex="-1">bun <a class="header-anchor" href="#bun" aria-label="Permalink to “bun”">​</a></h2><ul><li>bun 是一个新一代的包管理工具，它结合了 npm 和 pnpm 的优点，同时还提供了更快的安装速度和更小的磁盘占用。</li></ul><h3 id="优点-2" tabindex="-1">优点 <a class="header-anchor" href="#优点-2" aria-label="Permalink to “优点”">​</a></h3><ul><li>安装速度快，性能优越。</li></ul><h3 id="缺点-2" tabindex="-1">缺点 <a class="header-anchor" href="#缺点-2" aria-label="Permalink to “缺点”">​</a></h3><ul><li>新工具，社区和生态系统相对较小。</li></ul>`,22)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};